import { useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useNavigate } from 'react-router'

import {
  Box,
  Button,
  Card,
  Container,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material'

import PageTitleWrapper from 'src/components/PageTitleWrapper'

import { type ClubLeaderRequestData, useCreateClubLeader } from 'src/hooks/api/admin'

const ClubLeaderRegisterPage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const navigate = useNavigate()
  const createClubLeader = useCreateClubLeader()
  const [clubLeaderInformation, setClubLeaderInformation] = useState<ClubLeaderRequestData>({
    clubName: '',
    studentId: '',
    email: ''
  })

  const handleLeaderInformationChange: React.ChangeEventHandler<HTMLInputElement> = event => {
    const { name, value } = event.target
    setClubLeaderInformation(prevClubLeaderInformation => ({
      ...prevClubLeaderInformation,
      [name]: value
    }))
  }

  const handleRegisterButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    createClubLeader.mutate(clubLeaderInformation)
  }

  const handleAdminButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    navigate('/admin')
  }

  return (
    <>
      <Helmet>
        <title>동아리 회장 등록 - KLUB</title>
      </Helmet>
      <PageTitleWrapper>
        <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" spacing={2}>
          <Box>
            <Typography variant={isMobile ? 'h4' : 'h3'}>동아리 회장 등록</Typography>
            <Typography color="text.secondary" sx={{ mt: 1 }}>
              동아리명, 학번, 이메일로 회장 권한을 연결합니다.
            </Typography>
          </Box>
          <Button variant="outlined" onClick={handleAdminButtonClick}>
            어드민 페이지
          </Button>
        </Stack>
      </PageTitleWrapper>
      <Container maxWidth="lg">
        <Card sx={{ p: { xs: 2, md: 3 }, boxShadow: theme.header.boxShadow }}>
          <Grid container alignItems="center" spacing={2}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="동아리명"
                name="clubName"
                id="clubName"
                value={clubLeaderInformation.clubName}
                helperText="정확한 동아리명을 입력해주세요"
                onChange={handleLeaderInformationChange}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="동아리장 학번"
                required
                name="studentId"
                id="club-leader-student-id"
                fullWidth
                value={clubLeaderInformation.studentId}
                onChange={handleLeaderInformationChange}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                label="동아리장 이메일"
                name="email"
                id="email"
                fullWidth
                value={clubLeaderInformation.email}
                onChange={handleLeaderInformationChange}
              />
            </Grid>
            <Grid display="flex" item xs={12} justifyContent="flex-end">
              <Button variant="contained" color="success" onClick={handleRegisterButtonClick}>
                등록
              </Button>
            </Grid>
          </Grid>
        </Card>
      </Container>
    </>
  )
}

export default ClubLeaderRegisterPage
